-- Relay foundation: organization-scoped data with RLS. Apply in the Supabase SQL editor or CLI.
create type public.membership_role as enum ('owner','admin','member');
create type public.project_status as enum ('draft','active','paused','completed','archived');
create type public.task_status as enum ('todo','in_progress','blocked','completed','cancelled');
create type public.task_priority as enum ('low','medium','high','urgent');
create type public.agent_run_status as enum ('pending','running','waiting_for_approval','completed','failed','cancelled');
create type public.agent_action_status as enum ('planned','executing','waiting_for_approval','approved','rejected','completed','failed');
create type public.approval_status as enum ('pending','approved','rejected','cancelled');
create type public.actor_type as enum ('human','agent','system');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 1 and 200),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.memberships(organization_id uuid references public.organizations on delete cascade,user_id uuid references auth.users on delete cascade,role public.membership_role not null default 'member',created_at timestamptz not null default now(),primary key(organization_id,user_id));
create table public.projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,owner_id uuid not null references auth.users, name text not null check(char_length(name) between 1 and 200),description text,status public.project_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_requirements(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,description text not null,created_at timestamptz not null default now());
create table public.tasks(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,title text not null,description text,status public.task_status not null default 'todo',priority public.task_priority not null default 'medium',assignee_id uuid references auth.users,due_date date,creator_id uuid not null references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.resources(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,name text not null,category text not null,description text,availability text,location text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.resource_matches(id uuid primary key default gen_random_uuid(),resource_id uuid not null references public.resources on delete cascade,project_id uuid not null references public.projects on delete cascade,score numeric,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.documents(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,title text not null,type text not null,content text,creator_id uuid not null references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.document_versions(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents on delete cascade,version_number integer not null check(version_number > 0),content text not null,created_by uuid not null references auth.users,created_at timestamptz not null default now(),unique(document_id,version_number));
create table public.schedules(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,task_id uuid references public.tasks on delete set null,start_time timestamptz,end_time timestamptz,status text,notes text,created_at timestamptz not null default now(),check(end_time is null or start_time is null or end_time >= start_time));
create table public.agent_runs(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,status public.agent_run_status not null default 'pending',intent text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.agent_actions(id uuid primary key default gen_random_uuid(),agent_run_id uuid not null references public.agent_runs on delete cascade,status public.agent_action_status not null default 'planned',description text not null,reason text,consequence text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tool_calls(id uuid primary key default gen_random_uuid(),agent_action_id uuid not null references public.agent_actions on delete cascade,tool_name text not null,input jsonb,output jsonb,status text not null,error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.approvals(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects on delete cascade,agent_action_id uuid references public.agent_actions on delete set null,status public.approval_status not null default 'pending',reason text,consequence text,requested_at timestamptz not null default now(),decided_at timestamptz,decided_by uuid references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.approval_events(id uuid primary key default gen_random_uuid(),approval_id uuid not null references public.approvals on delete cascade,actor_id uuid references auth.users,event_type text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.activity_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,project_id uuid references public.projects on delete cascade,actor_type public.actor_type not null,actor_id uuid references auth.users,event_type text not null,description text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index projects_org_idx on public.projects(organization_id);create index tasks_project_idx on public.tasks(project_id);create index resources_project_search_idx on public.resources(project_id,category,location,availability);create index activity_events_project_idx on public.activity_events(project_id,created_at desc);create index approvals_project_idx on public.approvals(project_id,status);
create or replace function public.is_org_member(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.memberships where organization_id=org_id and user_id=auth.uid())$$;
alter table public.organizations enable row level security;alter table public.memberships enable row level security;alter table public.projects enable row level security;alter table public.project_requirements enable row level security;alter table public.tasks enable row level security;alter table public.resources enable row level security;alter table public.resource_matches enable row level security;alter table public.documents enable row level security;alter table public.document_versions enable row level security;alter table public.schedules enable row level security;alter table public.agent_runs enable row level security;alter table public.agent_actions enable row level security;alter table public.tool_calls enable row level security;alter table public.approvals enable row level security;alter table public.approval_events enable row level security;alter table public.activity_events enable row level security;
create policy "members view organizations" on public.organizations for select using(public.is_org_member(id));create policy "members view memberships" on public.memberships for select using(public.is_org_member(organization_id));
create policy "members access projects" on public.projects for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy "members access project requirements" on public.project_requirements for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access tasks" on public.tasks for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access resources" on public.resources for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access resource matches" on public.resource_matches for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access documents" on public.documents for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access versions" on public.document_versions for all using(exists(select 1 from public.documents d join public.projects p on p.id=d.project_id where d.id=document_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.documents d join public.projects p on p.id=d.project_id where d.id=document_id and public.is_org_member(p.organization_id)));
create policy "members access schedules" on public.schedules for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access runs" on public.agent_runs for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access actions" on public.agent_actions for all using(exists(select 1 from public.agent_runs r join public.projects p on p.id=r.project_id where r.id=agent_run_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.agent_runs r join public.projects p on p.id=r.project_id where r.id=agent_run_id and public.is_org_member(p.organization_id)));
create policy "members access tool calls" on public.tool_calls for all using(exists(select 1 from public.agent_actions a join public.agent_runs r on r.id=a.agent_run_id join public.projects p on p.id=r.project_id where a.id=agent_action_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.agent_actions a join public.agent_runs r on r.id=a.agent_run_id join public.projects p on p.id=r.project_id where a.id=agent_action_id and public.is_org_member(p.organization_id)));
create policy "members access approvals" on public.approvals for all using(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.projects p where p.id=project_id and public.is_org_member(p.organization_id)));
create policy "members access approval events" on public.approval_events for all using(exists(select 1 from public.approvals a join public.projects p on p.id=a.project_id where a.id=approval_id and public.is_org_member(p.organization_id))) with check(exists(select 1 from public.approvals a join public.projects p on p.id=a.project_id where a.id=approval_id and public.is_org_member(p.organization_id)));
create policy "members access activity" on public.activity_events for all using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
